<script setup lang="ts">
import { benefitText } from '@/shared/i18n'
import {computed,ref} from 'vue'
import {ArrowRight,ArrowLeftRight,CheckCircle2,AlertTriangle} from 'lucide-vue-next'
import {data,num,money,sum,aggregateFinance,months} from './data'
import {reportedMonth,scopeMonths} from './report-output'
import MetricValue from './MetricValue.vue'
import ComparisonScope from './ComparisonScope.vue'
const props=defineProps<{year:number;agency:string;selectedMonths:number[];period:string}>()
const emit=defineEmits<{period:[string];region:[string];family:[string]}>()
const left=ref('1'),right=ref('7')
const localScopes = ref([{district:'',agency:props.agency},{district:'',agency:props.agency}])
function regionData(region:string,index:number){
  const selected = localScopes.value[index]!
  if(selected.district) return {amount:0,plan:0,gap:0,rate:null,measures:0,monthly:months.map(()=>null)}

  const lines=data.finance.filter(line=>(!selected.agency||line.o===selected.agency) &&
    props.selectedMonths.some(month=>reportedMonth(line,props.year,region,month)))
  const rows=lines.map(line=>aggregateFinance(line,props.year,region,props.selectedMonths))
  const planned=rows.filter(row=>row.plan>0)
  const plan=sum(planned.map(row=>row.plan)), paid=sum(planned.map(row=>row.total))
  const monthly=months.map((_,month)=>{
    if(!props.selectedMonths.includes(month)) return null
    const values=lines.map(line=>reportedMonth(line,props.year,region,month)).filter(value=>value!==undefined)
    return values.length?sum(values.map(value=>value.s)):null
  })
  return {amount:sum(rows.map(row=>row.total))*1e9,plan:plan*1e9,
    gap:sum(planned.map(row=>Math.max(0,row.plan-row.total)))*1e9,
    rate:plan?paid/plan*100:null,measures:rows.length,monthly}
}
const comparison=computed(()=>[regionData(left.value,0),regionData(right.value,1)])
const difference=computed(()=>comparison.value[1]!.amount-comparison.value[0]!.amount)
const monthsLabel=computed(()=>scopeMonths(props.selectedMonths))
const sourceFacts=[{label:'To‘lov yozuvlari',value:data.demographics.rows,detail:'2025-yil nafaqa bazasi'},{label:'Moliyaviy choralar',value:data.finance.length,detail:'Summa mavjud choralar'},{label:'Tumanlar',value:data.districts.length,detail:'Nafaqa bazasi qamrovi'},{label:'Oila pasportlari',value:data.families.length,detail:'Manbadagi namuna'},{label:'Nazorat toifalari',value:data.audit.length,detail:'Tekshiruv signallari'},{label:'Hududlar',value:data.regions.length,detail:'Respublika qamrovi'}]
</script>
<template><section class="insights-explorer"><Teleport defer to="#support-filter-fields"><label>{{ benefitText("Yil boshidan jamlangan davr") }}<select :value="period.startsWith('upto')?period:''" @change="emit('period',($event.target as HTMLSelectElement).value||'all')"><option value="">{{ benefitText("Davrni tanlash") }}</option><option v-for="(month,i) in months" :key="month" :value="'upto'+i">{{ benefitText(month) }}{{ benefitText(" oyigacha") }}</option></select></label></Teleport><div class="source-facts"><div v-for="fact in sourceFacts" :key="fact.label"><span>{{ benefitText(fact.label) }}</span><strong><MetricValue :value="fact.value"/></strong><small>{{ benefitText(fact.detail) }}</small></div></div><section class="comparison-panel"><header><div><p>{{ benefitText("HUDUDLARNI SOLISHTIRISH") }}</p><h3>{{ benefitText("Qo‘llab-quvvatlash choralarining ijro holati") }}</h3></div><span>{{ benefitText(monthsLabel) }} · {{ benefitText(year) }}{{ benefitText(year!==2025?' · namunaviy yil':'') }}</span></header><Teleport defer to="#support-filter-fields"><div class="comparison-select"><select v-model="left" :aria-label="benefitText('Birinchi taqqoslanadigan hudud')"><option v-for="(name,i) in data.regions" :key="i" :value="String(i)">{{ benefitText(name) }}</option></select><button class="icon-button" :aria-label="benefitText('Taqqoslash hududlarini almashtirish')" @click="[left,right]=[right,left]"><ArrowLeftRight :size="18"/></button><select v-model="right" :aria-label="benefitText('Ikkinchi taqqoslanadigan hudud')"><option v-for="(name,i) in data.regions" :key="i" :value="String(i)">{{ benefitText(name) }}</option></select></div></Teleport><div class="comparison-grid"><article v-for="(item,index) in comparison" :key="index"><label class="comparison-region">{{ benefitText('Viloyat') }}<select :value="index===0?left:right" @change="index===0 ? left=($event.target as HTMLSelectElement).value : right=($event.target as HTMLSelectElement).value"><option v-for="(name,i) in data.regions" :key="i" :value="String(i)">{{ benefitText(name) }}</option></select></label><ComparisonScope :region="index===0?left:right" :agency="agency" @change="localScopes[index]=$event" @family="emit('family',$event)"/><div class="comparison-amount"><h4>{{ benefitText(data.regions[+(index===0?left:right)]) }}</h4><small>{{ benefitText("Ko‘rsatilgan ko‘mak") }}</small><strong v-if="item.measures"><MetricValue :value="item.amount/1e9" :decimals="1"/><span>{{ benefitText("mlrd so‘m") }}</span></strong><p v-else class="history-note">{{ benefitText("Tanlangan hudud va idora bo‘yicha moliyaviy ma’lumot mavjud emas.") }}</p></div><div class="comparison-spark" role="img" :aria-label="benefitText('Oylik taqsimot: '+item.monthly.map((v,i)=>months[i]+' '+(v===null?'—':num(v,1)+' mlrd')).join(', '))"><i v-for="(value,i) in item.monthly" :key="i" :style="{height:value===null?0:Math.max(2,value/Math.max(...item.monthly.map(month=>month??0),1)*100)+'%',opacity:selectedMonths.includes(i)?1:.2}" :title="benefitText(months[i]+' '+(value===null?'Ma’lumot yo‘q':money(value*1e9)+' so‘m'))"/></div><div class="compare-numbers"><div><span>{{ benefitText("Summa mavjud choralar") }}</span><b>{{ benefitText(item.measures) }}</b></div><div><span>{{ benefitText("Vedomost summasi") }}</span><b>{{ benefitText(item.plan?money(item.plan)+' so‘m':'Mavjud emas') }}</b></div><div><span>{{ benefitText("Vedomost ijrosi") }}</span><b :class="item.rate!==null&&item.rate<95?'warn':'good'">{{ benefitText(item.rate===null?'—':num(item.rate,1)+'%') }}</b></div><div><span>{{ benefitText("To‘lanmagan qism") }}</span><b class="warn">{{ benefitText(item.plan?money(item.gap)+' so‘m':'—') }}</b></div></div><button class="compare-open" @click="emit('region',index===0?left:right)">{{ benefitText("Shu hududni bosh sahifaga qo‘llash ") }}<ArrowRight :size="14"/></button></article></div><div class="comparison-result"><component :is="left===right?CheckCircle2:ArrowLeftRight" :size="17"/><span>{{ benefitText(!comparison[0]!.measures||!comparison[1]!.measures?'Solishtirish uchun manbada hududiy ma’lumot yetarli emas.':left===right?'Bir xil hudud tanlangan. Solishtirish uchun ikkinchi hududni o‘zgartiring.':benefitText(data.regions[+right])+'dagi ko‘mak '+benefitText(data.regions[+left])+'ga nisbatan '+money(Math.abs(difference))+' so‘m '+(difference>=0?'ko‘p.':'kam.')) }}</span></div><p class="history-note"><AlertTriangle :size="12"/>{{ benefitText("Hududiy summalar manbada mavjud IHMA choralarini qamrab oladi. Hududlar farqi samaradorlik reytingi emas. Vedomost ijrosi faqat reja mavjud choralar bo‘yicha hisoblangan.") }}</p></section></section></template>
<style scoped>.insights-explorer{display:grid;gap:20px}.source-facts{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--border);border-radius:12px;background:var(--card)}.source-facts>div{padding:17px;border-right:1px solid var(--border);display:grid;gap:7px}.source-facts>div:last-child{border:0}.source-facts span{font-size:11px;color:var(--muted-foreground)}.source-facts strong{font-size:24px;color:#416ca7;font-weight:700}.source-facts small{font-size:11px;color:var(--muted-foreground)}.history-player,.comparison-panel{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:23px}.history-heading{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.history-heading>div{margin-right:auto}.history-heading p,.comparison-panel header p{font-size:11px;color:var(--muted-foreground);font-weight:700;letter-spacing:.1em}.history-heading h3,.comparison-panel h3{font-size:17px;font-weight:700;margin-top:7px}.history-heading label{font-size:11px;color:var(--muted-foreground);display:flex;align-items:center;gap:7px}.history-slider{padding:22px 4px 0}.history-slider>input{width:100%;padding:0!important;accent-color:#4b7bd3;cursor:pointer}.history-slider>div{display:flex;justify-content:space-between;margin-top:12px}.history-slider button{font-size:11px;color:var(--muted-foreground);display:flex;flex-direction:column;align-items:center;gap:6px}.history-slider button i{height:4px;width:4px;border-radius:50%;background:#c8d3e4}.history-slider button.selected{color:#3a71be;font-weight:700}.history-slider button.selected i{background:#4a84ce}.history-note{display:flex;gap:7px;align-items:flex-start;font-size:11px!important;color:var(--muted-foreground)!important;line-height:1.8;margin-top:16px}.history-note svg{flex-shrink:0;margin-top:3px}.comparison-panel>header{display:flex;align-items:center;justify-content:space-between;gap:20px}.comparison-panel>header>span{font-size:11px;color:var(--muted-foreground)}.comparison-select{display:grid;grid-template-columns:1fr 40px 1fr;gap:14px;margin:22px 0 18px}.comparison-select select{max-width:none}.comparison-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px}.comparison-grid article{border:1px solid var(--border);border-radius:10px;padding:20px}.comparison-amount small{font-size:11px;color:var(--muted-foreground)}.comparison-amount strong{display:flex;gap:10px;align-items:baseline;font-size:30px;font-weight:700;color:#4675b7;margin-top:8px}.comparison-amount strong>span:last-child{font-size:11px;font-weight:400;color:var(--muted-foreground)}.comparison-spark{height:65px;display:flex;align-items:flex-end;gap:8px;margin:20px 0}.comparison-spark>i{flex:1;background:#9cbceb;border-radius:4px 4px 0 0;transition:height .5s,opacity .5s}.comparison-grid article:nth-child(2) .comparison-spark>i{background:#87c5b6}.compare-numbers>div{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid var(--border);font-size:11px}.compare-numbers span{color:var(--muted-foreground)}.compare-numbers b{color:#537dab}.compare-numbers b.warn{color:#cb9360}.compare-numbers b.good{color:#39a58a}.compare-open{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:#5282c4;width:100%;border-top:1px solid var(--border);padding-top:16px;margin-top:10px}.comparison-result{display:flex;align-items:center;gap:10px;background:var(--muted);padding:14px;border-radius:8px;margin-top:18px;font-size:12px;color:var(--muted-foreground)}.comparison-result svg{flex-shrink:0}@media(max-width:1050px){.source-facts{grid-template-columns:repeat(3,1fr)}.source-facts>div{border-bottom:1px solid var(--border)}}@media(max-width:650px){.source-facts{grid-template-columns:repeat(2,1fr)}.comparison-grid{gap:10px;grid-template-columns:1fr}.comparison-select{grid-template-columns:1fr 35px;gap:8px}.comparison-select>select:last-child{grid-column:1/-1}.comparison-panel>header{flex-wrap:wrap}.history-player,.comparison-panel{padding:16px}}
.comparison-region { display: grid; gap: 5px; font-size: 12px; }.comparison-region select { padding: 8px; border: 1px solid var(--border); border-radius: 8px; background: var(--card); color: var(--foreground); }
</style>
